function paintCalendar(s,focus=false){if(!s.popup)return;const body=s.popup.querySelector('[data-calendar-months]');body.innerHTML=Array.from({length:s.panels},(_,i)=>monthGrid(s,shiftMonth(s.month,i),i)).join('');const selected=s.draft?.[0];s.popup.querySelector('[data-date-instruction]').textContent=s.p.mode==='single'?'选择一个日期':!selected?'请选择开始日期':!s.draft[1]?'请选择结束日期 · 较早日期将重新开始选择':`${s.draft[0]} → ${s.draft[1]}`;if(focus){const el=[...body.querySelectorAll('[data-date]:not(:disabled)')].find(x=>x.dataset.date===s.focusDate&&x.dataset.other==='false')||body.querySelector('[data-date]:not(:disabled)');el?.focus()}}
