node.addEventListener('click',e=>{const d=e.target.closest('[data-date]'),nav=e.target.closest('[data-month-shift]'),pre=e.target.closest('[data-preset]');if(nav){const shift=nav.dataset.monthShift;s.month=shiftMonth(s.month,Number(shift));paintCalendar(s);node.querySelector(`[data-month-shift="${shift}"]`)?.focus();return}if(pre){const v=preset(pre.dataset.preset);if(v.every(x=>allowed(s,x))&&!containsDisabled(s,v)){commitDate(s,v)}else fieldError(s,'快捷范围包含不可选日期，请手动选择');return}if(!d||d.disabled)return;const v=d.dataset.date;if(s.p.mode==='single'){commitDate(s,v);return}if(!s.draft[0]||s.draft[1]||v<s.draft[0])s.draft=[v,''];else {if(containsDisabled(s,[s.draft[0],v])){fieldError(s,'范围内包含不可选日期，请重新选择');return}commitDate(s,[s.draft[0],v]);return}s.focusDate=v;paintCalendar(s,true)});
