function timeRender(p={}){const uid=id();return shell('time-picker',p,`<label class="v-field" for="${uid}">${E(p.label||'开始时间')}<span class="ui-time-input"><input id="${uid}" class="v-input" data-time-value aria-label="${E(p.label||'开始时间')}" name="${E(p.name||'time')}" value="${E(p.value||'')}" placeholder="HH:mm" autocomplete="off" ${p.disabled||p.readonly||['disabled','readonly'].includes(p.state)?'disabled':''} ${p.readonly||p.state==='readonly'?'readonly':''}><button type="button" class="ui-field-icon" data-ui-action="time-open" aria-label="选择时间" aria-haspopup="dialog" aria-expanded="false" ${p.disabled||p.readonly||['disabled','readonly'].includes(p.state)?'disabled':''}>${clockIcon()}</button></span></label><p class="v-error" data-time-error role="status"></p>`)}
