function numberRender(p={}){return shell('number',p,`<label class="v-field">${E(p.label||'总学时')}<span class="ui-number-input"><input class="v-input" type="number" name="${E(p.name||'hours')}" value="${E(p.value??32)}" min="${E(p.min??1)}" max="${E(p.max??200)}" step="${E(p.step??1)}" ${p.disabled||p.readonly||['disabled','readonly'].includes(p.state)?'disabled':''}><span>${E(p.unit??'学时')}</span></span></label><p class="v-error" data-number-error role="status"></p>`)}
