function pageItems(page,pages){if(pages<=7)return Array.from({length:pages},(_,i)=>i+1);if(page<=4)return [1,2,3,4,5,'next',pages];if(page>=pages-3)return [1,'prev',...Array.from({length:5},(_,i)=>pages-4+i)];return [1,'prev',page-1,page,page+1,'next',pages]}
