function resourceRender(p={}){const items=p.items??[{id:'r1',name:'人工智能基础 · 课程说明.txt',type:'TXT',size:'2.4 KB',version:'v1',description:'课程目标、课堂活动与教学安排的本地示例。'},{id:'r2',name:'实训任务与提交材料要求.txt',type:'TXT',size:'1.8 KB',version:'v2',description:'说明实训输入、成果形式与核对要求。'},{id:'r3',name:'课堂讨论与学习活动参考资料及适用范围说明.txt',type:'TXT',size:'3.1 KB',version:'v1',description:'使用资料前请按当前课程检查适用范围。'}];return shell('resource',{...p,items},`<div class="ui-resource-head"><label class="ui-search"><span class="v-sr">搜索资源</span>${I('search',16)}<input type="search" placeholder="搜索名称或类型" data-resource-search></label><div class="v-row">${button(I('file',15)+' 列表','resource-list','soft','aria-label="列表视图" aria-pressed="true"')}${button(I('grid',15)+' 卡片','resource-grid','ghost','aria-label="卡片视图" aria-pressed="false"')}</div></div><div data-resource-items></div><p class="v-caption" data-resource-status role="status">本地虚构资料；下载提供示例文本，不解析 Office 或 PDF。</p>`)}
