function init(root){if(states.has(root))return;const p=JSON.parse(root.dataset.uiConfig||'{}');if(p.state==='disabled')p.disabled=true;if(p.state==='readonly')p.readonly=true;const type=root.dataset.uiType;const s={root,p,type,value:initial(type,p),abort:new AbortController(),popup:null};states.set(root,s);if(type==='pagination'){s.value=p.page||1;paintPagination(s)}if(type==='date'){showDate(s)}if(type==='number')s.value=root.querySelector('input').value===''?null:Number(root.querySelector('input').value);if(type==='collapse')s.value=p.openKeys||['goals'];if(type==='calendar'){s.month=(p.month&&validDate(p.month+'-01')?p.month+'-01':today().slice(0,7)+'-01');paintEvents(s)}if(type==='notification'){s.items=p.items.map(x=>({...x}));paintNotifications(s)}if(type==='tree-select'){s.value=p.value??(p.multiple?[]:null);showTreeValue(s)}if(type==='person-picker'){s.value=Array.isArray(p.value)?p.value.filter(v=>p.items.some(x=>x.id===v)):[];paintPeople(s)}if(type==='resource'){s.view=p.view||'list';paintResources(s)}bindControl(s)}
function layoutChat(root){if(root._vLayout)return;const update=()=>{if(!root.isConnected)return;const compact=root.clientWidth<720;root.dataset.compact=String(compact);const panel=root.querySelector('dialog.v-history-sheet');if(!compact&&panel){panel.close();const aside=panel.querySelector('.v-chat-history');if(aside){aside.querySelector('[data-history-close]')?.remove();root.prepend(aside)}panel.remove()}const result=root.querySelector('[data-content-workspace]');if(result&&root.dataset.workspace==='true'&&root.clientWidth<1000&&!root.querySelector('.v-workspace-sheet'))U.hydrate(root)};if(typeof ResizeObserver!=='undefined'){root._vLayout=new ResizeObserver(update);root._vLayout.observe(root)}update()}
function history(root){let sheet=root.querySelector('dialog.v-history-sheet');if(sheet?.open){sheet.close();return}if(!sheet){sheet=document.createElement('dialog');sheet.className='v-history-sheet';sheet.setAttribute('aria-label','会话列表');const aside=root.querySelector('.v-chat-history');const closeButton=document.createElement('button');closeButton.type='button';closeButton.className='v-btn v-icon-btn';closeButton.dataset.historyClose='';closeButton.setAttribute('aria-label','关闭会话列表');closeButton.innerHTML=I('close',16);closeButton.onclick=()=>sheet.close();aside.prepend(closeButton);sheet.append(aside);root.append(sheet);sheet.addEventListener('click',e=>{if(e.target===sheet)sheet.close();if(e.target.closest('[data-v-action=thread-open],[data-v-action=chat-new]'))sheet.close()})}sheet.showModal();sheet.querySelector('input,button')?.focus()}
