const renderers={pagination:paginationRender,cascade:p=>treeSelectRender({...p,leafOnly:true,label:p.label||'院系与专业',nodes:p.nodes??treeData.map(n=>({...n,children:(n.children||[]).map(x=>({id:x.id,label:x.label}))}))}),date:dateRender,'time-picker':timeRender,number:numberRender,collapse:collapseRender,'tree-select':treeSelectRender,'academic-term':termRender,rate:rateRender,calendar:calendarRender,'feedback-result':resultRender,empty:emptyRender,notification:notificationRender,'image-preview':imageRender,'person-picker':personRender,resource:resourceRender,confirm:confirmRender};Object.entries(renderers).forEach(([key,render])=>U.register(key,render));
